statements:
ALTER TABLE truco_arena_der.copia_carta_partida DROP CONSTRAINT ck_copia_posicion;
ALTER TABLE truco_arena_der.copia_carta_partida ADD CONSTRAINT ck_copia_posicion CHECK (posicion_original BETWEEN 1 AND 20);
ALTER TABLE truco_arena_der.partida DROP CONSTRAINT ck_partida_motivo;
ALTER TABLE truco_arena_der.partida ADD CONSTRAINT ck_partida_motivo CHECK(motivo_cierre IS NULL OR motivo_cierre IN ('VIDA_CERO','LIMITE_TURNOS','REINICIO','ABANDONO','INACTIVIDAD'));
ALTER TABLE truco_arena_der.partida DROP CONSTRAINT ck_partida_cierre;
ALTER TABLE truco_arena_der.partida ADD CONSTRAINT ck_partida_cierre CHECK(
 (fecha_fin IS NULL AND motivo_cierre IS NULL AND ganador_posicion IS NULL) OR
 (fecha_fin IS NOT NULL AND fecha_fin>=fecha_inicio AND motivo_cierre IS NOT NULL AND
 ((motivo_cierre IN ('REINICIO','LIMITE_TURNOS') AND (motivo_cierre<>'REINICIO' OR ganador_posicion IS NULL))
 OR (motivo_cierre IN ('VIDA_CERO','ABANDONO','INACTIVIDAD') AND ganador_posicion IS NOT NULL))));
ALTER TABLE truco_arena_der.jugador ALTER COLUMN fecha_alta SET DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE truco_arena_der.mazo ALTER COLUMN descripcion SET DEFAULT '';
ALTER TABLE truco_arena_der.mazo ALTER COLUMN fecha_creacion SET DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE truco_arena_der.partida ALTER COLUMN fecha_inicio SET DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE truco_arena_der.partida ALTER COLUMN version SET DEFAULT 1;
ALTER TABLE truco_arena_der.participante_partida ALTER COLUMN vida_heroe SET DEFAULT 20;
ALTER TABLE truco_arena_der.turno ALTER COLUMN fecha_apertura SET DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE truco_arena_der.solicitud_operacion ALTER COLUMN fecha_registro SET DEFAULT CURRENT_TIMESTAMP;
CREATE INDEX idx_copia_zona ON truco_arena_der.copia_carta_partida(id_participante,zona,posicion_original);
CREATE INDEX idx_turno_abierto ON truco_arena_der.turno(id_partida,fecha_cierre);
